from pathlib import Path

app = Path('src/App.tsx')
app.write_text(\"\"\"import { useState } from 'react';
import { Button, Flex, Text, useThemeType } from '@gravity-ui/uikit';
import type { ThemeType } from '@gravity-ui/uikit';

interface AppProps {
  theme: ThemeType;
  onThemeChange: (theme: ThemeType) => void;
}

export function App({ theme, onThemeChange }: AppProps) {
  return (
    <Flex direction=\"column\" gapRow=\"4\" alignItems=\"flex-start\" style={{ padding: 24 }}>
      <Text variant=\"header-1\">Переключатель темы</Text>
      <Button
        size=\"l\"
        view=\"outlined\"
        onClick={() => onThemeChange(theme === 'light' ? 'dark' : 'light')}
      >
        {theme === 'light' ? 'Включить тёмную тему' : 'Включить светлую тему'}
      </Button>
      <Text variant=\"body-1\">Текущая тема: {theme}</Text>
    </Flex>
  );
}
\"\"\")

main = Path('src/main.tsx')
main.write_text(\"\"\"import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React, { useState } from 'react';
import ReactDOM from 'react-dom/client';
import { ThemeProvider } from '@gravity-ui/uikit';
import type { ThemeType } from '@gravity-ui/uikit';

import { App } from './App';

function Root() {
  const [theme, setTheme] = useState<ThemeType>('light');

  return <App theme={theme} onThemeChange={setTheme} />;
}

ReactDOM.createRoot(document.getElementById('root')"'!).render(
  <React.StrictMode>
    <ThemeProvider theme={theme}>
      <Root />
    </ThemeProvider>
  </React.StrictMode>,
);
""")
PY'

